
public class A1Q11 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int i = 42 + 45 -48 -5;  // = 34
		int j = 5 + 5 -8 + 2; // = 4
		int ans = i % j; // Statement 3
		int modified = i/j; // Just replace modulus with division
		System.out.println("Value of Ans= "+ ans);
		System.out.println("Modified Value of Ans= "+ modified);
	}

}
